python3 -c "
import json
with open('agent/trajectory.json') as f:
    data = json.load(f)
steps = data['steps']
for i, s in enumerate(steps):
    print('=== STEP', i, s.get('timestamp'), '===')
    msg = s.get('message')
    if isinstance(msg, str):
        print('MSG:', msg[:500])
    elif isinstance(msg, dict):
        print('MSG dict keys:', msg.keys())
    tcs = s.get('tool_calls')
    if tcs:
        for tc in tcs:
            print('TOOL:', tc.get('name') if isinstance(tc, dict) else tc)
            if isinstance(tc, dict):
                args = tc.get('arguments') or tc.get('input')
                if args:
                    s_args = json.dumps(args)
                    print('  ARGS:', s_args[:300])
"

